CREATE TABLE public.loyalty_rules (id boolean PRIMARY KEY DEFAULT true CHECK(id), enabled boolean NOT NULL DEFAULT false, rupees_per_point integer NOT NULL DEFAULT 100 CHECK(rupees_per_point>0), point_value numeric NOT NULL DEFAULT 1 CHECK(point_value>0), minimum_redemption integer NOT NULL DEFAULT 100 CHECK(minimum_redemption>0), referral_bonus integer NOT NULL DEFAULT 0 CHECK(referral_bonus>=0));
GRANT SELECT ON public.loyalty_rules TO anon; GRANT SELECT,INSERT,UPDATE ON public.loyalty_rules TO authenticated; GRANT ALL ON public.loyalty_rules TO service_role;
ALTER TABLE public.loyalty_rules ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public reward rules" ON public.loyalty_rules FOR SELECT USING(true);
CREATE POLICY "Admin reward rules" ON public.loyalty_rules FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE UNIQUE INDEX loyalty_order_earning ON public.loyalty_ledger(user_id,order_id,reason) WHERE order_id IS NOT NULL;
CREATE FUNCTION public.redeem_reward_points(_points integer) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _rules public.loyalty_rules; _balance integer; _code text; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in to redeem rewards'; END IF; PERFORM id FROM public.profiles WHERE id=auth.uid() FOR UPDATE; SELECT * INTO _rules FROM public.loyalty_rules WHERE id=true; IF NOT FOUND OR NOT _rules.enabled THEN RAISE EXCEPTION 'Rewards are disabled'; END IF; SELECT coalesce(sum(points),0) INTO _balance FROM public.loyalty_ledger WHERE user_id=auth.uid(); IF _points<_rules.minimum_redemption OR _points>_balance THEN RAISE EXCEPTION 'Invalid redemption amount'; END IF; _code:='IHSREWARD-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,16)); INSERT INTO public.coupons(code,discount_type,discount_value,min_order,is_active,max_uses,expires_at) VALUES(_code,'flat',_points*_rules.point_value,_points*_rules.point_value,true,1,now()+interval '30 days'); INSERT INTO public.loyalty_ledger(user_id,points,reason,created_by) VALUES(auth.uid(),-_points,'Redeemed for '||_code,auth.uid()); RETURN _code; END $$;
REVOKE ALL ON FUNCTION public.redeem_reward_points(integer) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.redeem_reward_points(integer) TO authenticated;
CREATE FUNCTION public.assign_referral(_code text DEFAULT NULL) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _own text; _referrer uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; SELECT referral_code INTO _own FROM public.profiles WHERE id=auth.uid() FOR UPDATE; IF _own IS NULL THEN _own:='IHS-'||upper(substr(replace(auth.uid()::text,'-',''),1,12)); UPDATE public.profiles SET referral_code=_own WHERE id=auth.uid(); END IF; IF _code IS NOT NULL AND length(trim(_code))>0 THEN SELECT id INTO _referrer FROM public.profiles WHERE referral_code=upper(trim(_code)) AND id<>auth.uid(); IF _referrer IS NULL THEN RAISE EXCEPTION 'Invalid referral code'; END IF; UPDATE public.profiles SET referred_by=_referrer WHERE id=auth.uid() AND referred_by IS NULL AND NOT EXISTS(SELECT 1 FROM public.orders WHERE user_id=auth.uid()); IF NOT FOUND THEN RAISE EXCEPTION 'Referral is already set or a purchase already exists'; END IF; END IF; RETURN _own; END $$;
REVOKE ALL ON FUNCTION public.assign_referral(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.assign_referral(text) TO authenticated;
CREATE FUNCTION public.award_order_points() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _rules public.loyalty_rules; _referrer uuid; _earned integer; BEGIN IF NEW.status::text='delivered' AND NEW.payment_status::text='paid' AND NEW.user_id IS NOT NULL AND (OLD.status::text<>'delivered' OR OLD.payment_status::text<>'paid') THEN SELECT * INTO _rules FROM public.loyalty_rules WHERE id=true AND enabled=true; IF FOUND THEN _earned:=floor(NEW.subtotal/_rules.rupees_per_point); IF _earned>0 THEN INSERT INTO public.loyalty_ledger(user_id,points,reason,order_id) VALUES(NEW.user_id,_earned,'Purchase reward',NEW.id) ON CONFLICT DO NOTHING; END IF; SELECT referred_by INTO _referrer FROM public.profiles WHERE id=NEW.user_id; IF _referrer IS NOT NULL AND _rules.referral_bonus>0 AND NOT EXISTS(SELECT 1 FROM public.orders WHERE user_id=NEW.user_id AND status::text='delivered' AND id<>NEW.id) THEN INSERT INTO public.loyalty_ledger(user_id,points,reason,order_id) VALUES(_referrer,_rules.referral_bonus,'Referral reward',NEW.id) ON CONFLICT DO NOTHING; END IF; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER award_loyalty AFTER UPDATE OF status,payment_status ON public.orders FOR EACH ROW EXECUTE FUNCTION public.award_order_points();